      {
        "text": "Tesla's revenue facts using the standard concepts exist from FY2011 through FY2026.",
        "evidence": ["E-51869f"]
      },
      {
        "text": "No revenue facts for Tesla exist before FY2011.",
        "evidence": ["E-f332d0"]
      },
      {
        "text": "Tesla has no XBRL facts of any concept before FY2011.",
        "evidence": ["E-f160de"]
      }
    ],
    "inferences": [
      {
        "text": "The start of revenue data coincides with Tesla's IPO and transition to accelerated filer status, which mandated XBRL tagging of standard revenue concepts.",
        "basis": "Claims about FY2011 start and known IPO timing (external knowledge)."
      },
      {
        "text": "Prior to FY2011 Tesla likely used custom XBRL tags or omitted standard revenue elements, resulting in absent revenue facts.",
        "basis": "Claims showing zero XBRL facts before FY2011 and hypothesis H-1a5c05 about reporting status change."
      }
    ],
    "hypothesis_verdicts": [
      {
        "id": "H-34ece3",
        "status": "supported",
        "evidence": ["E-f160de", "E-f332d0"],
        "why": "No XBRL facts (any concept) appear for Tesla before FY2011, indicating missing standard revenue tags."
      },
      {
        "id": "H-620cc6",
        "status": "refuted",
        "evidence": ["E-f160de"],
        "why": "Zero XBRL facts before FY2011 shows absence of tags, not just zero values."
      },
      {
        "id": "H-dec1ef",
        "status": "refuted",
        "evidence": ["E-f160de"],
        "why": "No XBRL facts at all before FY2011, so filtering null period_frame cannot explain the gap."
      },
      {
        "id": "H-1a5c05",
        "status": "supported",
        "evidence": ["E-51869f", "E-f160de", "E-f332d0"],
        "why": "Revenue facts appear exactly when Tesla became an accelerated filer post‑IPO, requiring standard revenue XBRL tagging."
      }
    ]
  }
